const input = $input.first().json || {};

function fail({ code, message, details = [], inputSnapshot = {} }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C2-A1",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        destination: {
          type: "google_sheets",
          spreadsheet_id: input.config?.spreadsheet_id || null,
          sheet_name: input.config?.sheet_name || null,
          record_id: null
        },
        write: {
          status: "failed",
          fields_written: []
        },
        payload: input.input?.payload || {},
        metadata: input.input?.metadata || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log",
        input_snapshot: inputSnapshot
      }
    }
  ];
}

function getByPath(obj, path) {
  return path.split(".").reduce((acc, key) => {
    if (acc && Object.prototype.hasOwnProperty.call(acc, key)) {
      return acc[key];
    }
    return undefined;
  }, obj);
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty.",
    inputSnapshot: input
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object.",
    inputSnapshot: input
  });
}

const validatedInput = input.input;
const config = input.config || {};

if (validatedInput.success !== true) {
  return fail({
    code: "UPSTREAM_VALIDATION_FAILED",
    message: "C2-A1 will not write records when upstream validation failed.",
    details: [
      {
        upstream_component: validatedInput.component_id || null,
        upstream_error: validatedInput.error || null
      }
    ],
    inputSnapshot: input
  });
}

if (!config.spreadsheet_id) {
  return fail({
    code: "MISSING_SPREADSHEET_ID",
    message: "config.spreadsheet_id is required.",
    inputSnapshot: input
  });
}

if (!config.sheet_name) {
  return fail({
    code: "MISSING_SHEET_NAME",
    message: "config.sheet_name is required.",
    inputSnapshot: input
  });
}

if (!config.field_map || typeof config.field_map !== "object") {
  return fail({
    code: "MISSING_FIELD_MAP",
    message: "config.field_map is required.",
    inputSnapshot: input
  });
}

const fieldMap = config.field_map;

// Fixed column order based on target sheet headers
const headers = [
  "Event ID",
  "Event Type",
  "Name",
  "Email",
  "Company",
  "Message",
  "Source",
  "Origin",
  "Environment",
  "Received At",
  "Written At"
];

const rowObject = {};
const fieldsWritten = [];

for (const [sourcePath, targetHeader] of Object.entries(fieldMap)) {
  const value = getByPath(validatedInput, sourcePath);
  rowObject[targetHeader] = value ?? "";
  fieldsWritten.push(targetHeader);
}

// Add system fields if not mapped directly
rowObject["Received At"] = validatedInput.received_at || "";
rowObject["Written At"] = new Date().toISOString();

const rowValues = headers.map(header => rowObject[header] ?? "");

const range = `${config.sheet_name}!A:K`;

return [
  {
    json: {
      stop_before_http: false,
      request: {
        spreadsheet_id: config.spreadsheet_id,
        range,
        url: `https://sheets.googleapis.com/v4/spreadsheets/${config.spreadsheet_id}/values/${encodeURIComponent(range)}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`,
        body: {
          values: [rowValues]
        }
      },
      context: {
        component_id: "C2-A1",
        component_version: "v1",
        event_id: validatedInput.event_id || null,
        event_type: validatedInput.event_type || null,
        destination: {
          type: "google_sheets",
          spreadsheet_id: config.spreadsheet_id,
          sheet_name: config.sheet_name,
          record_id: null
        },
        write: {
          status: "prepared",
          fields_written: fieldsWritten
        },
        payload: validatedInput.payload || {},
        metadata: validatedInput.metadata || {},
        next_action: config.default_next_action || "notify_team"
      }
    }
  }
];

const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      destination: prepared.destination,
      write: prepared.write,
      payload: prepared.payload,
      metadata: prepared.metadata,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];

const httpOutput = $input.first().json || {};
const prepared = $("Prepare Sheet Append Request").first().json;
const context = prepared.context;

let recordId = null;

if (httpOutput.updates && httpOutput.updates.updatedRange) {
  recordId = httpOutput.updates.updatedRange;
}

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      destination: {
        ...context.destination,
        record_id: recordId
      },
      write: {
        status: "created",
        fields_written: context.write.fields_written
      },
      payload: context.payload,
      metadata: context.metadata,
      error: null,
      next_action: context.next_action
    }
  }
];
